    title: string;
    description: string | null;
    model_id: string;
    created_at: string;
    updated_at: string;
    sources?: NotebookSource[];
    docs?: NotebookDoc[];
}

export interface NotebookSource {
    id: number;
    notebook_id: number;
    title: string;
    source_type: 'pdf' | 'docx' | 'audio' | 'video' | 'url' | 'obsidian';
    origin_path: string | null;
    status: 'pending' | 'processing' | 'ready' | 'error';
    error_msg: string | null;
    word_count: number;
    created_at: string;
}

export interface NotebookDoc {
    id: number;
    notebook_id: number;
    doc_type: 'summary' | 'study_guide' | 'faq' | 'timeline' | 'briefing';
    title: string;
    content: string;
    pdf_path: string | null;
    obsidian_path: string | null;
    model_id: string | null;
    created_at: string;
}

export interface NotebookMessage {
    id: number;
    role: 'user' | 'assistant';
    content: string;
    sources_used: string | null;
    created_at: string;
}

export interface RagCitation {
    chunk_id: number;
    source_title: string;
    excerpt: string;
}

export type DocType = 'summary' | 'study_guide' | 'faq' | 'timeline' | 'briefing';

// ─── Notebooks ──────────────────────────────────────────────────────────────

export async function createNotebook(title: string): Promise<Notebook> {
    const r = await apiFetch('/api/notebook/notebooks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title })
    });
    return r.json();
}

export async function listNotebooks(): Promise<Notebook[]> {
    const r = await apiFetch('/api/notebook/notebooks');
    return r.json();
}

export async function getNotebook(id: number): Promise<Notebook> {
    const r = await apiFetch(`/api/notebook/notebooks/${id}`);
    return r.json();
}

export async function updateNotebook(id: number, patch: { title?: string; description?: string }): Promise<void> {
    await apiFetch(`/api/notebook/notebooks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patch)
    });
}

export async function deleteNotebook(id: number): Promise<void> {
    await apiFetch(`/api/notebook/notebooks/${id}`, { method: 'DELETE' });
}

// ─── Sources ────────────────────────────────────────────────────────────────

export async function uploadSources(notebookId: number, files: File[]): Promise<any[]> {
    const form = new FormData();
    files.forEach(f => form.append('files', f));
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/sources/upload`, {
        method: 'POST',
        body: form
    });
    return r.json();
}

export async function addUrlSource(notebookId: number, url: string): Promise<any> {
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/sources/url`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
    });
    return r.json();
}

export async function addObsidianSource(notebookId: number, vaultPath: string): Promise<any> {
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/sources/obsidian`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ vault_path: vaultPath })
    });
    return r.json();
}

export async function deleteSource(sourceId: number): Promise<void> {
    await apiFetch(`/api/notebook/sources/${sourceId}`, { method: 'DELETE' });
}

export async function listSources(notebookId: number): Promise<NotebookSource[]> {
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}`);
    const nb: Notebook = await r.json();
    return nb.sources || [];
}

// ─── Messages ───────────────────────────────────────────────────────────────

export async function loadMessages(notebookId: number): Promise<NotebookMessage[]> {
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/messages`);
    return r.json();
}

// ─── RAG Chat Stream ─────────────────────────────────────────────────────────

export interface StreamCallbacks {
    onToken: (token: string) => void;
    onCitation: (citation: RagCitation) => void;
    onDone: (content: string) => void;
    onError: (msg: string) => void;
}

export function streamChat(notebookId: number, query: string, model: string, callbacks: StreamCallbacks): EventSource {
    const url = `${API_ORIGINS[0]}/api/notebook/notebooks/${notebookId}/stream?command=${encodeURIComponent(query)}&model=${encodeURIComponent(model)}`;
    const es = new EventSource(url);
    let full = '';

    es.addEventListener('token', (e: MessageEvent) => {
        try {
            const { token } = JSON.parse(e.data);
            full += token;
            callbacks.onToken(token);
        } catch (_) {}
    });

    es.addEventListener('citation', (e: MessageEvent) => {
        try {
            callbacks.onCitation(JSON.parse(e.data));
        } catch (_) {}
    });

    es.addEventListener('done', (e: MessageEvent) => {
        es.close();
        try { const { content } = JSON.parse(e.data); full = content || full; } catch (_) {}
        callbacks.onDone(full);
    });

    es.addEventListener('error', (e: MessageEvent) => {
        es.close();
        let msg = 'STREAM_FAILED';
        try { msg = JSON.parse((e as any).data)?.message || msg; } catch (_) {}
        callbacks.onError(msg);
    });

    es.onerror = () => { es.close(); callbacks.onError('CONNECTION_LOST'); };

    return es;
}

